 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
            c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
            mask = [[int(grid[rr][cc] != 0) for cc in range(c0, c1 + 1)] for rr in range(r0, r1 + 1)]
            colors = {grid[rr][cc] for rr, cc in cells}
            objects.append((r0, c0, mask, colors, len(cells)))

    # Repeated constructs contain identical large color-pattern fragments.
    # Differing colors inside the same shape are the encoded answer symbols.
    best = None
    for i, a in enumerate(objects):
        for b in objects[i + 1:]:
            if len(a[2]) != len(b[2]) or len(a[2][0]) != len(b[2][0]):
                continue
            if a[2] != b[2] or min(a[4], b[4]) < 8:
                continue
            # Ignore pairs that have identical coloring too: seek altered cells.
            mismatches = []
            for r in range(len(a[2])):
                for c in range(len(a[2][0])):
                    if a[2][r][c] and b[2][r][c]:
                        # Recover colors by coordinate from source grid.
                        ca = grid[a[0] + r][a[1] + c]
                        cb = grid[b[0] + r][b[1] + c]
                        if ca != cb:
                            mismatches.append((r, c))
            if mismatches:
                score = (len(mismatches), min(a[4], b[4]))
                if best is None or score > best[0]:
                    best = (score, mismatches, len(a[2]), len(a[2][0]))
    if best:
        _, cells, oh, ow = best
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        hit = set(cells)
        return [[8 if (r, c) in hit else 0 for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    # Fallback: compare the repeated motif instances at their aligned upper-left.
    return [[8]]
