 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            objects.append([row[x0:x1 + 1] for row in grid[y0:y1 + 1]])

    def orientations(a):
        out = []
        for _ in range(4):
            out.append(a)
            out.append([row[::-1] for row in a])
            a = [list(row) for row in zip(*a[::-1])]
        return out

    best = None
    for i, a in enumerate(objects):
        for b in objects[i + 1:]:
            for t in orientations(b):
                if len(a) != len(t) or len(a[0]) != len(t[0]):
                    continue
                diff = [[a[r][c] != t[r][c] for c in range(len(a[0]))]
                        for r in range(len(a))]
                n = sum(sum(row) for row in diff)
                if not n:
                    continue
                rank = (len(a) * len(a[0]) - n, -n)
                if best is None or rank > best[0]:
                    best = (rank, diff)
    if best is None:
        return [[0]]
    diff = best[1]
    rs = [r for r in range(len(diff)) if any(diff[r])]
    cs = [c for c in range(len(diff[0])) if any(diff[r][c] for r in range(len(diff)))]
    return [[8 if diff[r][c] else 0 for c in range(min(cs), max(cs) + 1)]
            for r in range(min(rs), max(rs) + 1)]
